if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_command() {
    if _argc_util_has_path_prefix; then
        _argc_util_comp_path
        return 0
    fi
    _argc_util_comp_command
}

_choice_component_all() {
    rustup $(_argc_util_param_select_options --toolchain) component list 2>/dev/null | sed 's/ (installed)$//' | _argc_util_comp_parts -
}

_choice_component_installed() {
    rustup $(_argc_util_param_select_options --toolchain) component list --installed 2>/dev/null
}

_choice_default_toolchain() {
    _choice_toolchain_all
    printf '%s\n' none
}

_choice_run_command() {
    if [[ "${#argc__positionals[@]}" -le 2 ]]; then
        _choice_command
    else
        _argc_util_comp_subcommand 1
    fi
}

_choice_target_all() {
    rustup $(_argc_util_param_select_options --toolchain) target list 2>/dev/null | sed 's/ (installed)$//' | _argc_util_comp_parts -
}

_choice_target_installed() {
    rustup $(_argc_util_param_select_options --toolchain) target list --installed 2>/dev/null
}

_choice_toolchain_all() {
    _choice_toolchain_installed
    printf '%s\n' stable beta nightly
}

_choice_toolchain_binary() {
    local dir file
    dir="$(_helper_toolchain_dir)" || return 0
    [[ -n "$dir" && -d "$dir/bin" ]] || return 0
    for file in "$dir"/bin/*; do
        [[ -f "$file" && -x "$file" ]] && printf '%s\n' "${file##*/}"
    done
}

_choice_toolchain_installed() {
    local host name
    host="$(rustup show 2>/dev/null | sed -n 's/^Default host: //p')"
    rustup toolchain list 2>/dev/null | sed 's/ (.*//' | while IFS= read -r name; do
        if [[ -n "$host" && "$name" == *-"$host" ]]; then
            printf '%s\n' "${name%-$host}"
        else
            printf '%s\n' "$name"
        fi
    done | gawk '!seen[$0]++'
}

_choice_toolchain_man() {
    local dir file name
    dir="$(_helper_toolchain_dir)" || return 0
    [[ -n "$dir" && -d "$dir/share/man/man1" ]] || return 0
    for file in "$dir"/share/man/man1/*.1; do
        [[ -f "$file" ]] || continue
        name="${file##*/}"
        printf '%s\n' "${name%.1}"
    done
}

_helper_toolchain_dir() {
    local home toolchain
    home="$(rustup show home 2>/dev/null)" || return 0
    toolchain="$(rustup show active-toolchain 2>/dev/null | gawk '{print $1; exit}')"
    [[ -n "$home" && -n "$toolchain" ]] || return 0
    printf '%s/toolchains/%s' "$home" "$toolchain"
}
# <<< CHOICES

command eval "$(argc --argc-eval "$0" "$@")"
